package main

import (
	"fmt"
	"sync"
)

func main() {
	var data int
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		data = 42 // write
		wg.Done() // Done happens-before Wait returns -> creates the edge
	}()
	wg.Wait() // establishes happens-before between the goroutine's writes and here
	fmt.Println(data) // Output: 42 (guaranteed, because of the WaitGroup edge)
}

package main

import "sync"

func main() {
	var x int
	var wg sync.WaitGroup
	for i := 0; i < 2; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			x++ // DATA RACE: unsynchronized read-modify-write, no happens-before edge
		}()
	}
	wg.Wait()
	// x is undefined behavior: `go run -race` reports 'WARNING: DATA RACE'.
	_ = x
}

