import "fmt"

var data int

func main() {
	done := make(chan struct{})
	go func() {
		data = 42    // write happens-before the close (program order)
		close(done)  // close happens-before the receive below returns
	}()
	<-done               // receive completes -> the edge is established
	fmt.Println(data)    // Output: 42 (write -> close -> receive -> read chain)
