import (
	"fmt"
	"sync"
)

var (
	once sync.Once
	cfg  string
)

func get() string {
	once.Do(func() { cfg = "loaded" }) // completion of f happens-before every Do return
	return cfg
}

func main() {
	var wg sync.WaitGroup
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func() { defer wg.Done(); _ = get() }() // all callers safely observe cfg
	}
	wg.Wait()
	fmt.Println(get()) // Output: loaded
}

