var (
	data  int
	ready atomic.Bool
)

func main() {
	go func() {
		data = 99        // write happens-before the atomic Store (program order)
		ready.Store(true) // SC store: synchronizes-with a Load that observes true
	}()
	for !ready.Load() { // once this sees true, the Store happened-before it
	}
	fmt.Println(data) // Output: 99 (data-write -> Store -> Load -> read)
}

package main

import (
	"fmt"
	"sync"
)

func main() {
	var mu sync.Mutex
	n := 0
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			mu.Lock() // every access ordered by the mutex -> data-race-free
			n++
			mu.Unlock()
		}()
	}
	wg.Wait()
	// Because the program is race-free, DRF-SC guarantees a sequentially
	// consistent result: exactly 100, every run.
	fmt.Println(n) // Output: 100
}

