package solution

import (
	"sync"
	"sync/atomic"
	"testing"
)

func TestGetOnceAndConsistent(t *testing.T) {
	var calls int32
	p := New(func() int {
		atomic.AddInt32(&calls, 1) // count how many times compute runs
		return 42
	})

	const n = 100
	var wg sync.WaitGroup
	results := make([]int, n)
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(idx int) {
			defer wg.Done()
			results[idx] = p.Get() // distinct index -> no shared-slot race
		}(i)
	}
	wg.Wait()

	if got := atomic.LoadInt32(&calls); got != 1 {
		t.Fatalf("compute ran %d times, want 1", got)
	}
	for i, r := range results {
		if r != 42 {
			t.Fatalf("results[%d]=%d, want 42", i, r)
		}
	}
}

