package solution

import "sync"

type Lazy[T any] struct {
	once sync.Once // ensures init runs exactly once
	val  T         // cached result, published via once.Do
}

// Value runs init at most once across all goroutines and returns the
// cached result. once.Do guarantees init's completion happens-before
// the return of every Value call, so val is safely visible to all.
func (l *Lazy[T]) Value(init func() T) T {
	l.once.Do(func() {
		l.val = init()
	})
	return l.val
}

package solution

import "sync/atomic"

// SnapshotStore holds an immutable *T published via an atomic pointer.
// Readers Load lock-free; a writer Publishes a fully-built replacement.
type SnapshotStore[T any] struct {
	p atomic.Pointer[T] // SC atomic: Store happens-before a Load that observes it
}

// Publish atomically installs snap as the current snapshot. The caller must
// treat *snap as immutable after publishing (build a new one to change it).
func (s *SnapshotStore[T]) Publish(snap *T) {
	s.p.Store(snap) // all writes that built *snap happen-before this Store
}

// Load returns the current snapshot with no lock. Because the publishing
// Store happens-before this Load, the returned *T is fully constructed.
func (s *SnapshotStore[T]) Load() *T {
	return s.p.Load()
}

